package com.seckill.web;
import com.seckill.common.*; import com.seckill.infrastructure.*; import org.springframework.data.redis.core.StringRedisTemplate; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/admin/seckill") public class AdminController { private final SeckillOrderMapper mapper; private final StringRedisTemplate redis; public AdminController(SeckillOrderMapper mapper,StringRedisTemplate redis){this.mapper=mapper;this.redis=redis;} @PostMapping("/{activityId}/sku/{skuId}/preheat") public ApiResult<Map<String,Object>> preheat(@PathVariable Long activityId,@PathVariable Long skuId){Integer stock=mapper.stock(skuId);if(stock==null)throw new BusinessException(404,"票档不存在");redis.opsForValue().set(SeckillKeys.stock(activityId,skuId),String.valueOf(stock));redis.delete(SeckillKeys.buyers(activityId,skuId));Map<String,Object> result=new HashMap<>();result.put("activityId",activityId);result.put("skuId",skuId);result.put("stock",stock);return ApiResult.ok(result);} }
